start-job.function:
job -> x -> {
	$job.jobPhase('collect');
	$job.jobMessage(#('Collecting the source records.'@en, 'Die Quelldatensätze werden gesammelt.'@de));
	count(1, 6).foreach(i -> {
		sleep(400);
		$job.jobProgress($i, 5);
	});
	$job.jobPhase('draft');
	$job.jobIndeterminate();
	$job.jobMessage(#('Drafting the report.'@en, 'Der Bericht wird entworfen.'@de));
	sleep(1500);
	$job.jobPhase('review');
	$job.jobMessage(#('Reviewing the draft.'@en, 'Der Entwurf wird geprüft.'@de));
	count(1, 4).foreach(i -> {
		sleep(300);
		$job.jobProgress($i, 3);
	});
	#('5 records processed.'@en, '5 Datensätze verarbeitet.'@de);
}

job -> x -> {
	$job.jobPhase('collect');
	$job.jobMessage(#('Reading the source.'@en, 'Die Quelle wird gelesen.'@de));
	sleep(800);
	throw(#('The source could not be read.'@en, 'Die Quelle konnte nicht gelesen werden.'@de));
}

body.init:
job -> x -> {
	$job.jobMessage(#('Naming the run.'@en, 'Der Lauf wird benannt.'@de));
	{'prefix': 'Bulk ' + dateFormat('HH:mm:ss').format(now()), 'count': 500};
}

step.expr:
job -> chunk -> state -> {
	$job.jobMessage(#('Creating the tickets {0} to {1}.'@en, 'Die Tickets {0} bis {1} werden angelegt.'@de)
		.fill($chunk[0], $chunk[$chunk.size() - 1]));
	sleep(4 * $chunk.size());
	$chunk.foreach(n -> {
		if($n % 97 == 0, throw(#('Ticket {0} cannot be created.'@en, 'Ticket {0} kann nicht angelegt werden.'@de).fill($n)), null);
		ticket = new(`demo.tickets:Ticket`);
		$ticket.set(`demo.tickets:Ticket#name`, $state['prefix'] + ' #' + $n);
	});
}

job -> chunk -> state -> {
	$job.jobMessage(#('Closing the tickets {0} to {1}.'@en, 'Die Tickets {0} bis {1} werden geschlossen.'@de)
		.fill($chunk[0], $chunk[$chunk.size() - 1]));
	sleep(4 * $chunk.size());
	names = $chunk.filter(n -> $n % 2 == 0).map(n -> $state['prefix'] + ' #' + $n);
	all(`demo.tickets:Ticket`)
		.filter(t -> $names.containsElement($t.get(`demo.tickets:Ticket#name`)))
		.foreach(t -> $t.set(`demo.tickets:Ticket#status`, `demo.tickets:TicketStatus#closed`));
}

body.finish:
job -> state -> {
	$job.jobMessage(#('Counting the imported tickets.'@en, 'Die importierten Tickets werden gezählt.'@de));
	imported = all(`demo.tickets:Ticket`)
		.filter(t -> $t.get(`demo.tickets:Ticket#name`).stringStartsWith($state['prefix']))
		.size();
	#('{0} tickets carry the name "{1}".'@en, '{0} Tickets tragen den Namen „{1}“.'@de).fill($imported, $state['prefix']);
}

step.expr:
job -> chunk -> state -> {
	$job.jobMessage(#('Deleting {0} tickets.'@en, '{0} Tickets werden gelöscht.'@de).fill($chunk.size()));
	$chunk.delete();
}
